input.script:
() => {
  const html = document.body.innerHTML;
  const idx = html.indexOf('Market Data');
  const idx2 = html.indexOf('market data');
  const idx3 = html.indexOf('Markets');
  const result = {};
  if (idx !== -1) {
    result.found = 'Market Data';
    result.context = html.substring(Math.max(0, idx-200), idx+500);
  }
  if (idx2 !== -1) {
    result.found2 = 'market data';
    result.context2 = html.substring(Math.max(0, idx2-200), idx2+500);
  }
  if (idx3 !== -1) {
    result.found3 = 'Markets';
    result.context3 = html.substring(Math.max(0, idx3-100), idx3+300);
  }
  return result;
}
